INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1200, 'Herne The Hunter &#8211; Vị chúa tể của rừng', 'herne-the-hunter', '<p>Herne the Hunter là một nhân vật trong truyền thuyết ở Anh. Herne the Hunter là một con ma cư trú tại Windsor Forest và Great Park ở Anh. Trên đầu của <strong>Herne the Hunter</strong> là một đôi gạc của nai và luôn cưỡi một con ngựa. Herne the Hunter xuất hiện từ vở kịch The Merry Wives of Windsor của William Shakespeare vào năm 1597. Đến giờ vẫn chưa thể biết chính xác rằng Shakespeare đã sáng tạo ra nhân vật Herne the Hunter hay đã đưa một phần Herne the Hunter từ trong truyền thuyết địa phương vào vở kịch.</p>
<h3>Herne the Hunter &#8211; Vụ chúa tể của rừng</h3>
<h4>Nguồn gốc ra đời Herne the Hunter</h4>
<p>Chúng ta có rất ít bằng chứng để tìm hiểu về nguồn gốc của Herne the Hunter. Tài liệu sớm nhất tìm thấy được là từ vở kịch của nhà soạn kịch vĩ đại Shakespeare (Tác phẩm nổi bật nhất của ông là Romeo and Juliet). Trong vở kịch The Merry Wives of Windsor (1597) có đoạn:</p>
<p><strong><em>Sometime a keeper here in Windsor Forest,</em></strong></p>
<p><strong><em>Doth all the winter-time, at still midnight,</em></strong></p>
<p><strong><em>Walk round about an oak, with great ragg&#8217;d horns;</em></strong></p>
<p><strong><em>And there he blasts the tree, and takes the cattle,</em></strong></p>
<p><strong><em>And makes milch-kine yield blood, and shakes a chain</em></strong></p>
<p><strong><em>In a most hideous and dreadful manner.</em></strong></p>
<p><strong><em>You have heard of such a spirit, and well you know</em></strong></p>
<p><strong><em>The superstitious idle-headed eld</em></strong></p>
<p><strong><em>Receiv&#8217;d, and did deliver to our age,</em></strong></p>
<p><strong><em>This tale of Herne the Hunter for a truth.</em></strong></p>
<dl>
<dd>&#8211; William Shakespeare, <i>The Merry Wives của Windsor</i></dd>
</dl>
<p><figure id="attachment_1202" aria-describedby="caption-attachment-1202" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1202" src="https://media.huynhhieutravel.com/Herne-the-Hunter.jpg" alt="Herne the Hunter" width="500" height="337" /><figcaption id="caption-attachment-1202" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Sau này vào năm 1602 cũng có một vài phiên bản khác xuất hiện về Herne the Hunter. Nhưng phiên bản này chủ yếu để dọa những đứa trẻ không ngoan. Nó nói về câu chuyện một con ma tàn bạo đi lại lang thang trong rừng với cái tên Herne the Hunter.</p>
<h4>Herne the Hunter trong thần thoại Anh</h4>
<p>Câu chuyện kể về một thợ săn tên Herne làm việc cho vua Richard II. Một thời gian sau có những người ghen tỵ với anh ta. Họ đã vu oan anh ta săn trộm trên mảnh đất của đức vua. Bị vu oan và những người bạn thân thiết ruồng bỏ. Herne đi lang thang khắp khu rừng và tự sát trên một cây sồi.</p>
<p><figure id="attachment_1205" aria-describedby="caption-attachment-1205" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1205" src="https://media.huynhhieutravel.com/Herne-the-Hunter4.jpg" alt="Herne the Hunter" width="500" height="353" srcset="https://media.huynhhieutravel.com/Herne-the-Hunter4.jpg 1024w, https://media.huynhhieutravel.com/Herne-the-Hunter4-370x260.jpg 370w, https://media.huynhhieutravel.com/Herne-the-Hunter4-768x542.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1205" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Ngoài ra có một số phiên bản khác. Theo đó Herne đã bị thương nặng khi cứu vua Richard II khỏi một vụ tông xe. Anh được một người xa lạ cứu chữa bằng cách lấy gạc của một con nai đã chết gắn vào trán. Nhưng người lạ đã yêu cầu Herne trả công bằng những kỹ năng của mình. Phát điên vì mất đi những kỹ năng mà anh yêu quý. Herne chạy trốn vào rừng, treo cổ tự sát bên một cây sồi. Tuy vậy, mỗi đêm anh vẫn hiện về dẫn đầu cuộc săn đuổi của mình ở Windsor Forest.</p>
<h4>Vì sao Herne the Hunter là chúa tể của rừng?</h4>
<p>Ngoài việc từng là một thợ săn tuyệt vời khi còn sống. Herne the Hunter còn có một đôi gạc sừng tuyệt vời. Theo quan niệm của người xưa ở phương Tây, chiếc sừng đại diện cho quyền lực của những vị thần cổ xưa. Nó thể hiện sự uy nghiêm và một sức mạnh thiên nhiên tuyệt vời.</p>
<p><figure id="attachment_1203" aria-describedby="caption-attachment-1203" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1203" src="https://media.huynhhieutravel.com/Herne-the-Hunter2.jpg" alt="Herne the Hunter" width="500" height="414" srcset="https://media.huynhhieutravel.com/Herne-the-Hunter2.jpg 1181w, https://media.huynhhieutravel.com/Herne-the-Hunter2-768x637.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1203" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Herne the Hunter xuất hiện với đôi sừng nai, cưỡi trên lưng một con ngựa đen, đem theo một cây cung bằng gỗ. Và đi cùng anh là những con chó săn bay lượn. Truyền thuyết kể lại nếu một ai đi ngang qua con đường của Herne the Hunter thì họ sẽ bị cuốn lấy và đi theo anh ta mãi mãi.</p>
<p>Sự xuất hiện của Herne the Hunter là một điềm xấu cho Hoàng gia. Herne the Hunter chỉ xuất hiện ở khu rừng Windsor Forest khi cần thiết. Và nó luôn là một thời kỳ khủng hoảng của quốc gia.</p>
', 'Herne the Hunter là một nhân vật trong truyền thuyết ở Anh. Herne the Hunter là một con ma cư trú tại Windsor Forest và Great Park ở Anh. Trên đầu của Herne the Hunter là một đôi gạc của nai và luôn cưỡi một con ngựa. Herne the Hunter xuất hiện từ vở kịch The Merry Wives of Windsor của William [&hellip;]', 1204, 'post', '2018-07-18 11:44:36', '2023-04-23 12:33:45');

